    // ───── СТРАНИЦА 1 ─────
    // Заголовок: «День 2 · Правила чтения»
    // Подзаголовок: «Буквы работают командой: сочетания, которые нужно знать наизусть.»
    // [Блок 1: Согласные сочетания] Таблица: Сочетание | Звук | Как читается | Примеры
    //   sh | /ʃ/ | русское «ш» | ship (корабль), shop (магазин), fish (рыба)
    //   ch | /tʃ/ | русское «ч» | chair (стул), cheese (сыр), lunch (обед)
    //   th | /θ/ или /ð/ | язык между зубами, без голоса или с голосом | think (думать), this (это), three (три)
    //   ph | /f/ | русское «ф» | phone (телефон), photo (фото), elephant (слон)
    //   ck | /k/ | русское «к», стоит в конце слова после короткой гласной | back (спина), black (чёрный), clock (часы)
    //   ng | /ŋ/ | носовой звук, «г» почти не слышно | sing (петь), long (длинный), morning (утро)
    //   wh | /w/ | губы трубочкой, h не читается | what (что), white (белый), when (когда), why (почему)
    // [Плашка 💡 Подсказка] Буква h после согласной почти никогда не читается отдельно: она «ломает» звук первой буквы (s+h = ш, c+h = ч, p+h = ф).
    // [Блок 2: Сочетания, которые читаются по-особому]
    //   tion | /ʃn/ | «шн» | station (станция), information (информация), nation (нация)
    //   igh | /aɪ/ | «ай», буквы g и h молчат | night (ночь), light (свет), high (высокий), right (правильный)
    // [Блок 3: Гласные сочетания] Таблица: Сочетание | Звук | Примеры
    //   ee | /iː/ долгий «и» | see (видеть), green (зелёный), meet (встречать)
    //   ea | /iː/ долгий «и» | eat (есть), tea (чай), sea (море). Исключения: bread /bred/ (хлеб), head /hed/ (голова)
    //   oo | /uː/ долгий «у» | moon (луна), food (еда), school (школа)
    //   oo | /ʊ/ короткий «у» | book (книга), look (смотреть), good (хороший)
    //   ow | /aʊ/ «ау» | cow (корова), now (сейчас), down (вниз)
    //   ow | /əʊ/ «оу» | snow (снег), show (показывать), yellow (жёлтый)
    //   ou | /aʊ/ «ау» | house (дом), out (наружу), mouth (рот)
    // [Плашка ⚠️ Ошибка] Не читай oo в слове book как долгое «у»: book /bʊk/ — звук короткий, как в «бук».
    // ───── СТРАНИЦА 2 ─────
    // [Блок 4: Магическая e] Правило: гласная + согласная + e на конце слова → e молчит, а гласная называет своё имя из алфавита.
    //   a: cap /kæp/ → cape /keɪp/ (шапка → плащ); mad → made (сумасшедший → сделал); plan → plane (план → самолёт)
