    //   o: hop /hɒp/ → hope /həʊp/ (прыгать → надеяться); not → note (не → заметка); rob → robe (грабить → халат)
    //   u: cub /kʌb/ → cube /kjuːb/ (детёныш → куб); tub → tube (ванна → трубка); cut → cute (резать → милый)
    //   e: these /ðiːz/ (эти) — редкий случай
    // [Плашка 🔊 Запомни] Короткая гласная «закрыта» согласной (cap), длинная гласная «открыта» магической e (cape). Одна буква e меняет значение слова!
    // [Плашка ⚠️ Исключения магической e] have /hæv/, give /gɪv/, live /lɪv/, come /kʌm/, love /lʌv/, some /sʌm/ — e на конце есть, а гласная короткая.
    // [Блок 5: Слова-исключения — запомнить целиком] Таблица: Слово | Произношение | Перевод
