    //   said | /sed/ «сэд» | сказал
    //   friend | /frend/ «фрэнд» | друг
    //   want | /wɒnt/ «уонт» | хотеть
    //   often | /ˈɒfn/ «офн» | часто (t не читается)
    //   know | /nəʊ/ «ноу» | знать (k не читается)
    //   you | /juː/ «ю» | ты, вы
    //   listen | /ˈlɪsn/ «лисн» | слушать (t не читается)
    // [Плашка 💡 Лайфхак] Немые буквы: k в know, w в two, t в listen и often, gh в night. Если слово кажется нечитаемым — ищи немую букву.
    // ───── СТРАНИЦА 3 ─────
