    // [Чек-лист дня] ☐ Читаю sh, ch, th, ph, ck, ng, wh  ☐ Знаю tion и igh  ☐ Различаю ee, ea, oo, ow, ou  ☐ Применяю магическую e  ☐ Помню 10 слов-исключений
