        // ТЕКСТ (дословно, что сказать): «Привет! Поздравляю: позади уже треть нашего курса! У тебя отличный запас существительных, и сегодня мы вдохнём в них жизнь — начнём учить сорок самых важных глаголов английского языка. Они покрывают около семидесяти процентов повседневной речи! Сегодня берём первую двадцатку: be, have, do, go, come, get, make, take, see, look, watch, hear, listen, say, tell, speak, know, think, want, need. И приятный сюрприз: с местоимениями I, you, we, they эти глаголы вообще не меняются! Берёшь слово из словаря, ставишь после I или we — и готово настоящее предложение. Поехали!»
