        // ВИЗУАЛ: преподаватель показывает пальцем на глаза (see), затем резко поворачивает голову и указывает на предмет (look at!), затем складывает руки как при просмотре кино (watch TV); в конце показывает на ухо (hear / listen)
        // ТЕКСТ (дословно, что сказать): «Разберём пять глаголов зрения и слуха: see, look, watch и hear, listen. Почему по-английски три разных слова для «видеть» и «смотреть»? Всё просто! See — это когда глаза открыты и ты просто видишь предмет сам собой: I see a park. Look — это когда ты специально направляешь взгляд на что-то: Look at me! Посмотри на меня! А watch — это когда ты долго наблюдаешь за тем, что движется или меняется, например за экраном: We watch TV. То же самое со слухом! Hear — звук сам попал в уши: I hear a bus. А listen — ты специально внимательно слушаешь: Listen to me! Кстати, в слове listen буква t молчит — говорим просто лисн!»
