        // ТЕКСТ (дословно, что сказать): «А теперь ещё одна знаменитая тройка: say, tell и speak. Все три переводятся как «говорить» или «сказать», но работают по-разному. Запоминай по короткому ключу! Первое: say — важно, ЧТО именно сказали. Например: say hello — сказать привет, say yes — сказать да. Второе: tell — важно, КОМУ ты это говоришь или рассказываешь. Сразу после tell идёт человек: tell me — скажи мне, tell my friend — расскажи другу. И третье: speak — это способность говорить и языки: I speak English, we speak Russian. Повтори три связки-маячка: say hello, tell me, speak English!»
