    //   buy | покупать | /baɪ/ | We buy bread. — Мы покупаем хлеб.
    // [Плашка 💡 Подсказка] В слове write буква w не читается: /raɪt/. В слове work звук /wɜːk/ — губы трубочкой, как для «у».
