    // [Плашка 🎯 Цель дня] Выучить 15 пар антонимов, цвета и чувства; понять порядок слов «прилагательное + существительное».
    // [Таблица 1: 15 пар антонимов (1–5)] Слово | Перевод | Произношение | Пара
    //   big | большой | /bɪɡ/ | small /smɔːl/ — маленький
