    // [Плашка 💡 Бонус] young /jʌŋ/ — молодой, tall /tɔːl/ — высокий. Пары: young — old, tall — short.
    // [Плашка ⚠️ Ошибка] easy — «лёгкий, простой» (задание), а light — «лёгкий по весу» (сумка). Не путай!
    // ───── СТРАНИЦА 2 ─────
    // [Таблица 4: Цвета] Цвет | Перевод | Произношение
    //   red | красный | /red/
    //   blue | синий, голубой | /bluː/
    //   green | зелёный | /ɡriːn/
    //   yellow | жёлтый | /ˈjeləʊ/
