    // [Таблица 5: Чувства и состояния] Слово | Перевод | Произношение | Пример
    //   happy | счастливый | /ˈhæpi/ | I am happy. — Я счастлив(а).
    //   sad | грустный | /sæd/ | She is sad. — Она грустит.
    //   angry | сердитый | /ˈæŋɡri/ | He is angry. — Он сердится.
