    //   busy | занятой | /ˈbɪzi/ | We are busy. — Мы заняты.
    //   ill | больной | /ɪl/ | He is ill. — Он болен.
    // [Плашка 💡 Подсказка] По-русски «мне холодно», а по-английски «I am cold» — «Я есть холодный». Используем to be: am, is, are.
