        // ТЕКСТ (дословно, что сказать): «Вместе с Present Simple почти всегда живут слова-маркеры частотности. Мы уже встречали их в восьмом дне, а теперь научимся ставить их на правильное место в предложении! Вспомним пятёрку от ста процентов до нуля: always — всегда, usually — обычно, often — часто, sometimes — иногда, never — никогда. Главное правило порядка слов: эти маркеры ставятся строго ПЕРЕД смысловым глаголом! Например: I always drink coffee. She usually gets up at seven. He never eats meat. А фразы со словом every — every day, every morning — мы ставим в самый конец предложения.»
