    //   She works. → Does she work? (НЕ Does she works?)
    //   He watches TV. → Does he watch TV? (НЕ Does he watches?)
    //   My brother studies. → Does my brother study?
    // [Блок 2: Из утверждения — вопрос] Таблица: Утверждение | Вопрос
    //   You speak English. | Do you speak English?
    //   They live in London. | Do they live in London?
    //   He works in a bank. | Does he work in a bank?
    //   She likes music. | Does she like music?
    //   The cat sleeps a lot. | Does the cat sleep a lot?
    // [Блок 3: Порядок слов] Помощник — подлежащее — глагол: Do (1) you (2) like (3) coffee (4)?
    //   Нельзя: You do like coffee? / Like you coffee? / Do like you coffee?
    // [Плашка ⚠️ Ошибка] Does he works? ✗ → Does he work? ✓   |   Do she like? ✗ → Does she like? ✓
    // ───── СТРАНИЦА 2 ─────
