        // ТЕКСТ (дословно, что сказать): «На вопрос с Do или Does англичане обычно отвечают коротко. Хочешь сказать да — Yes, и местоимение, и помощник. Do you work? Yes, I do. Does she work? Yes, she does. Хочешь сказать нет — No, местоимение и don't или doesn't. Do you work? No, I don't. Does he work? No, he doesn't. Обрати внимание: глагол work мы не повторяем! Не Yes, I work, а Yes, I do. И помощник в ответе такой же, как в вопросе: Do — I do, Does — she does. Повтори: Yes, I do. No, I don't. Yes, he does. No, she doesn't.»
