    //   where /weə/ | где, куда | Where are you from? — Откуда ты?
    //   when /wen/ | когда | When is your birthday? — Когда твой день рождения?
    //   who /huː/ | кто | Who is he? — Кто он?
    //   why /waɪ/ | почему, зачем | Why are you sad? — Почему ты грустный?
