    //   how many | сколько (исчисляемое) | How many brothers do you have? — Сколько у тебя братьев?
    //   whose /huːz/ | чей | Whose bag is this? — Чья это сумка?
    // [Плашка 💡 Подсказка] Почти все вопросительные слова начинаются на wh- (кроме how). Это «wh-questions».
    // [Блок 2: Формула с глаголом to be]
    //   Вопросительное слово + am / is / are + подлежащее?
    //   What is your name? | Where are you from? | How old are you? | Who is she? | When is the lesson?
    // [Блок 3: Формула с Do / Does]
