        // ВИЗУАЛ: преподаватель крупно; показывает на запястье (часы) на слове when, пожимает плечами на why, показывает руками «как дела» на how; на заднем плане — три карточки When / Why / How
        // ТЕКСТ (дословно, что сказать): «Давай разберём ещё три слова. When значит когда: When is your birthday? Why значит почему: Why are you sad? И чтобы ответить на why, мы используем слово because, то есть потому что. How значит как: How are you? А если поставить после how слово old, то мы спрашиваем про возраст: How old are you? Обрати внимание на звук в слове why: это w, губы трубочкой, не в! Повтори за мной: when, why, how. When is your birthday? How old are you?»
        videoNoteFile: 'assets/audio/day18_s06_when_why_how.mp4',
