        // ТЕКСТ (дословно, что сказать): «Теперь самое важное. Когда в вопросе есть обычный глагол, например live или work, нужен помощник Do или Does. Это то, что мы учили вчера. Формула такая: сначала вопросительное слово, потом Do или Does, потом кто, потом глагол без -s. Where do you live? What does she do? When do they work? Если в вопросе есть to be, помощник не нужен: Where are you? Но если глагол обычный, помощник обязателен. Не говори Where you live, говори Where do you live! Повтори: Where do you live? Where does he work?»
