    // [Блок 2: Слова-маркеры регулярности]
    //   always (всегда — 100%) · usually (обычно — 80%) · often (часто — 60%) · sometimes (иногда — 30%) · never (никогда — 0%)
    //   every day / week / morning (каждый день / неделю / утро) · on Mondays (по понедельникам)
    //   Порядок слов: маркер стоит ПЕРЕД обычным глаголом (I always drink coffee), но ПОСЛЕ am/is/are (He is always late).
    // ───── СТРАНИЦА 2 ─────
