        // ТЕКСТ (дословно, что сказать): «Давай вспомним золотую формулу английского вопроса в Present Simple. Считаем по пальцам! На первом месте — вопросительное слово, если оно есть: What, Where, When, Why, How. На втором месте — обязательно помощник do или does! На третьем — кто совершает действие: you, he, she, they. И на четвёртом — сам глагол в чистой форме без окончания s. Например: Where do you live? Или про него: Where does he live? Если вопрос начинается сразу с Do или Does, мы отвечаем коротко: Yes, I do или No, he doesn't. Потренируемся!»
