    // Подзаголовок: «Эти 30 слов нужно просто запомнить — зато они есть в каждом разговоре.»
    // [Блок 1: Что такое неправильный глагол]
    //   Правильный глагол: work → worked (добавляем -ed). Неправильный глагол: go → went (форма меняется, правила нет).
    //   V1 — форма из словаря (go). V2 — прошедшее время (went). Для Past Simple нужна именно V2.
    // [Таблица 1: Первая десятка] Глагол (V1) | Прошедшее (V2) | Произношение V2 | Перевод
    //   be | was / were | /wɒz/, /wɜː/ | быть
    //   have | had | /hæd/ | иметь
    //   do | did | /dɪd/ | делать
    //   go | went | /went/ | идти, ехать
