    //   take | took | /tʊk/ | брать
    //   see | saw | /sɔː/ | видеть
    //   give | gave | /geɪv/ | давать
    // [Плашка 💡 Подсказка] was — для I, he, she, it; were — для we, you, they. I was, she was, we were.
    // [Плашка ⚠️ Ошибка] Не говори goed, taked, seed, maked — таких слов нет! Правильно: went, took, saw, made.
    // [Примеры, 5 предложений]
    //   I went home. — Я пошёл домой. | She had a cat. — У неё был кот. | We saw a film. — Мы посмотрели фильм.
    //   He took my pen. — Он взял мою ручку. | They came late. — Они пришли поздно.
    // ───── СТРАНИЦА 2 ─────
    // [Таблица 2: Вторая десятка] Глагол (V1) | Прошедшее (V2) | Произношение V2 | Перевод
    //   know | knew | /njuː/ | знать
    //   think | thought | /θɔːt/ | думать
    //   say | said | /sed/ | сказать
    //   tell | told | /təʊld/ | рассказать, сообщить
    //   find | found | /faʊnd/ | находить
    //   buy | bought | /bɔːt/ | покупать
    //   eat | ate | /eɪt/ | есть, кушать
    //   drink | drank | /dræŋk/ | пить
    //   write | wrote | /rəʊt/ | писать
    //   read | read | /red/ | читать (пишется так же, читается иначе!)
    // [Таблица 3: Третья десятка] Глагол (V1) | Прошедшее (V2) | Произношение V2 | Перевод
    //   speak | spoke | /spəʊk/ | говорить
    //   sit | sat | /sæt/ | сидеть
    //   stand | stood | /stʊd/ | стоять
    //   run | ran | /ræn/ | бегать
    //   sleep | slept | /slept/ | спать
    //   leave | left | /left/ | уходить, оставлять
    //   meet | met | /met/ | встречать, знакомиться
    //   pay | paid | /peɪd/ | платить
    //   send | sent | /sent/ | отправлять
    //   lose | lost | /lɒst/ | терять
    // [Плашка 🔊 Важно] read (V1) читается /riːd/, а read (V2) читается /red/. По написанию их не отличить — смотри на смысл: «I read it yesterday» — прошедшее, значит /red/.
    // ───── СТРАНИЦА 3 ─────
    // [Блок 2: Группы по звучанию — так легче запомнить]
    //   • -ought: think — thought, buy — bought
    //   • -ept / -ent / -eft / -et / -ost: sleep — slept, send — sent, leave — left, meet — met, lose — lost
    //   • -old / -ound / -ood: tell — told, find — found, stand — stood
    //   • гласная на «a»: sit — sat, run — ran, drink — drank, come — came, give — gave, eat — ate, see — saw
    //   • гласная на «o / oo»: speak — spoke, write — wrote, take — took
