    //   8. Вопрос к «She ate an apple»: ... she ... an apple? (вставь слово)
    // [Ответы] 1. bought 2. ate 3. met 4. wrote 5. I didn’t go to school 6. Yesterday I saw a dog 7. /red/ 8. Did she eat an apple?
