        // ВИЗУАЛ: преподаватель крупно; слева на столе лист с надписью «WILL — сейчас», справа «GOING TO — план»; при каждом примере показывает на соответствующий лист
        // ТЕКСТ (дословно, что сказать): «Как выбрать между will и going to? Очень просто. Если ты решил что-то только что, в этот момент, говори will. Например, звонит телефон: I will answer it. Если решение было принято давно, и у тебя уже есть план, говори going to. Например: I am going to visit my grandmother tomorrow, у меня уже есть билет. Ещё will используем для обещаний и мнений: I will help you, I think it will be fun. А going to — когда ты видишь признаки будущего: тучи на небе, it is going to rain. Если сомневаешься, в разговоре почти всегда можно сказать и так, и так, и тебя поймут.»
