        // ТЕКСТ (дословно, что сказать): «Молодец! Сегодня ты научился говорить о будущем двумя способами. Ты знаешь формулу will плюс глагол и формулу am, is, are, going to плюс глагол. Ты понимаешь, когда выбирать will, а когда going to. И ты запомнил, что после if и when will ставить нельзя. Теперь твоя речь стала намного богаче. Напиши в чате ещё пару планов на завтра. А завтра у нас день диалогов: мы разберём, как знакомиться и заказывать кофе в кафе. See you tomorrow!»
